steps.script:
function transform(ctx) {
  var MAP = {};
  var suffix = "";
  var isp = (ctx.isp || "").trim();
  if (isp) { suffix = MAP[isp] !== undefined ? MAP[isp] : (isp.charAt(0) === "@" ? isp : ""); }
  var full = (ctx.username || "") + suffix;
  var out = { form_username: url_encode(full), form_password: url_encode(ctx.password || "") };

  return out;
}
